contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address adr, uint256 amount, uint256 v) public payable {
        require(address(this).balance >= amount);
        require(v > 0);
        // fund the contract
        c.multiplicate(address(this));
        (bool okFund, ) = address(c).call{value: amount}("");
        require(okFund);
        uint256 before = address(c).balance;
        // top-level state-changing call
        bool reverted;
        c.multiplicate(adr);
        reverted = false;
        // the above can never actually revert silently for the checker:
        // wrap in try via low-level is not allowed nested, so instead:
        uint256 after_ = address(c).balance;
        assert(after_ == before || after_ == 0);
    }
    receive() external payable {}
}

