        c.Command(address(this), ""){value: amount};
        // precondition: v is at least c's current balance
        require(v >= address(c).balance);
        uint256 before = address(c).balance + v;
        // deciding call, plain top-level statement
        c.multiplicate(address(this)){value: v};
        // rule: the whole (balance + v) was transferred out, leaving 0
        assert(address(c).balance == 0 && before >= v);
    }
    receive() external payable {}
}

